function check([m, n, r, c], actual) {
  if (!Array.isArray(actual) || actual.length !== m) return false;
  const where = new Array(m * n).fill(null);
  for (let i = 0; i < m; i++) {
    if (!Array.isArray(actual[i]) || actual[i].length !== n) return false;
    for (let j = 0; j < n; j++) {
      const v = actual[i][j];
      if (!Number.isInteger(v) || v < 0 || v >= m * n || where[v] !== null) return false;
      where[v] = [i, j];
    }
  }
  if (actual[r][c] !== 0) return false;
  for (let k = 1; k < m * n; k++) {
    const dr = Math.abs(where[k][0] - where[k - 1][0]);
    const dc = Math.abs(where[k][1] - where[k - 1][1]);
    if (Math.min(dr, dc) !== 1 || Math.max(dr, dc) !== 2) return false;
  }
  return true;
}

