function tourOfKnight(m, n, r, c) {
  const board = Array.from({ length: m }, () => new Array(n).fill(-1));
  const moves = [[-2, 1], [-1, 2], [1, 2], [2, 1], [2, -1], [1, -2], [-1, -2], [-2, -1]];
  const last = m * n - 1;
  const isFree = (row, col) => row >= 0 && row < m && col >= 0 && col < n && board[row][col] === -1;

  const exits = (row, col) => {
    let count = 0;
    for (const [dr, dc] of moves) {
      if (isFree(row + dr, col + dc)) count++;
    }
    return count;
  };

  const place = (row, col, step) => {
    board[row][col] = step;
    if (step === last) return true;
    const options = [];
    for (const [dr, dc] of moves) {
      const nextRow = row + dr;
      const nextCol = col + dc;
      if (isFree(nextRow, nextCol)) options.push([exits(nextRow, nextCol), nextRow, nextCol]);
    }
    options.sort((a, b) => a[0] - b[0]);
    for (const [, nextRow, nextCol] of options) {
      if (place(nextRow, nextCol, step + 1)) return true;
    }
    board[row][col] = -1;
    return false;
  };

  place(r, c, 0);
  return board;
}

