function tourOfKnight(m, n, r, c) {
  // Plain iterative depth-first search with an explicit path and no move ordering.
  const jumps = [[2, 1], [1, 2], [-1, -2], [-2, -1], [2, -1], [1, -2], [-1, 2], [-2, 1]];
  const path = [[r, c]];
  const used = new Set([r * n + c]);
  const tried = [0];
  while (path.length < m * n) {
    const top = path.length - 1;
    const [x, y] = path[top];
    let moved = false;
    while (tried[top] < 8) {
      const [dx, dy] = jumps[tried[top]++];
      const a = x + dx, b = y + dy;
      if (a >= 0 && a < m && b >= 0 && b < n && !used.has(a * n + b)) {
        path.push([a, b]);
        used.add(a * n + b);
        tried.push(0);
        moved = true;
        break;
      }
    }
    if (!moved) {
      if (path.length === 1) return [];
      const [a, b] = path.pop();
      used.delete(a * n + b);
      tried.pop();
    }
  }
  const board = Array.from({ length: m }, () => new Array(n).fill(0));
  path.forEach(([a, b], i) => { board[a][b] = i; });
  return board;
}

